		public preRenderFont creatRenderer(int size)
		{
			return new preRenderFont(this, size);
		}
		public void addChar(char v, params Triangle2D[] values)
		{
			lib.Add(v, values);
		}
		public void addChar(char v, params Vector2[] values)
		{
			int count = values.Length / 3;
			if (count * 3 == values.Length)
			{
				Triangle2D[] tr = new Triangle2D[count];
				for (int i = 0; i < count; i++)
				{
					tr[i] = new Triangle2D(values[i * 3], values[i * 3 + 1], values[i * 3 + 2]);
				}
				lib.Add(v, tr);
			}
		}
		public void addChar(char v, params double[] values)
		{
			int count = values.Length / 2;
			if (count * 2 == values.Length)
			{
				Vector2[] tr = new Vector2[count];
				for (int i = 0; i < count; i++)
				{
					tr[i] = new Vector2(values[i + i], values[i + i + 1]);
				}
				addChar(v, tr);
			}
		}
		Triangle2D[] GetTriangles(char v)
		{
			if (lib.ContainsKey(v))
			{
				return lib[v];
			}
			return defaultChar;
		}

		public void drawChar<T>(Map<T> map, double x, double y, double xSize, double ySize, char v, T value, bool cr = true)
		{
			Vector2 pos = new Vector2(x, y);
			Triangle2D[] tr = GetTriangles(v);
			foreach (var item in tr)
			{
				map.drawTriangle_(value, pos + new Vector2(item.p1.X * xSize, item.p1.Y * ySize), pos + new Vector2(item.p2.X * xSize, item.p2.Y * ySize), pos + new Vector2(item.p3.X * xSize, item.p3.Y * ySize), cr);
			}
		}
		public void drawChar<T>(Map<T> map, double x, double y, double xSize, double ySize, Triangle2D[] v, T value, bool cr = true)
		{
			Vector2 pos = new Vector2(x, y);
			Triangle2D[] tr = v;
			foreach (var item in tr)
			{
				map.drawTriangle_(value, pos + new Vector2(item.p1.X * xSize, item.p1.Y * ySize), pos + new Vector2(item.p2.X * xSize, item.p2.Y * ySize), pos + new Vector2(item.p3.X * xSize, item.p3.Y * ySize), cr);
			}
		}
		public void drawString<T>(Map<T> map, double x, double y, double xSize, double ySize, double dx, double dy, int maxCount, string v, T value, bool cr = true)
		{
			Vector2 pos0 = new Vector2(x, y);
			Vector2 pos1 = pos0;
			int co = 0;
			foreach (char c in v)
			{
				drawChar(map, pos1.X, pos1.Y, xSize, ySize, c, value, cr);
				pos1 = pos1.add(dx, 0);
				co++;
				if (co >= maxCount)
				{
					co = 0;
					pos0 = pos0.add(0, dy);
					pos1 = pos0;
				}
			}
		}


	
	}
	public class preRenderFont
	{
		Dictionary<char, Map<bool>> fonts = new Dictionary<char, Map<bool>>();
		Map<bool> defaultM;
		public readonly int size;

		public preRenderFont(FontManager manager, int size)
		{
			Map<bool> bitmap;
			defaultM = new Map<bool>(size, size);
			manager.drawChar(defaultM, 0, 0, size, size, FontManager.defaultChar,true);
			foreach (char c in manager.lib.Keys.ToArray())
			{
				bitmap = new Map<bool>(size, size);
				manager.drawChar(bitmap, 0, 0, size, size, c, true);
				fonts.Add(c, bitmap);
			}
			this.size = size;
		}

		public Map<bool> GetMap(char C)
		{
			if (fonts.ContainsKey(C))
			{
				return fonts[C];
			}
			return defaultM;
		}

		public void smooth(int times)
		{
			foreach(char c in fonts.Keys.ToArray())
			{
				Map<bool> mb=fonts[c];
				bitmap b=new bitmap(size,size);
				b.Foreach((x, y, d) => {
					if (mb[x,y])
					{
						d[x, y] = Colors.White;
					}
				});
				for(int i = 0; i < times; i++)
				{

				b=SpatialFilter .Guass.applyR(b);
				}
				b.Foreach((x, y, d) => {
					if (b[x, y]!=0)
					{
						mb[x, y] = true;
					}
				});
			}
			
		}
		public void drawChar<T>(Map<T> map, double x, double y, double xSize, double ySize, char v, T value)
		{
			Map<bool> mapb = GetMap(v);
			double kx = size / xSize;
			double ky = size / ySize;

			xSize = (int)Math.Min(xSize, map.Width - x);
			ySize = (int)Math.Min(ySize, map.Height - y);
			x = (int)x;
			y = (int)y;
			for (int i = 0; i < xSize; i++)
			{
				for (int j = 0; j < ySize; j++)
				{
					if (mapb[(int)(i * kx), (int)(j * ky)])
					{
						map[(int)(x + i), (int)(y + j)] = value;
					}
				}
			}
		}
		public void drawString<T>(Map<T> map, double x, double y, double xSize, double ySize, double dx, double dy, int maxCount, string v, T value)
		{
			Vector2 pos0 = new Vector2(x, y);
			Vector2 pos1 = pos0;
			int co = 0;
			foreach (char c in v)
			{
				drawChar(map, pos1.X, pos1.Y, xSize, ySize, c, value);
				pos1 = pos1.add(dx, 0);
				co++;
				if (co >= maxCount)
				{
					co = 0;
					pos0 = pos0.add(0, dy);
					pos1 = pos0;
				}
			}
		}
	}
}
